import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M2 8a1 1 0 1 0 2 0 1 1 0 0 0-2 0m3.83-1h4.34a3.001 3.001 0 1 1 0 2H5.83a3.001 3.001 0 1 1 0-2M13 7a1 1 0 1 0 0 2 1 1 0 0 0 0-2"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M2 10a1 1 0 1 0 2 0 1 1 0 0 0-2 0m3.83-1h8.34a3.001 3.001 0 1 1 0 2H5.83a3.001 3.001 0 1 1 0-2M17 9a1 1 0 1 0 0 2 1 1 0 0 0 0-2"] as readonly string[];

export const OneToOneIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="one-to-one" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
OneToOneIcon.displayName = `Blueprint6.Icon.OneToOneIcon`;

/**
 * @deprecated Use {@link OneToOneIcon} instead.
 */
export const OneToOne: typeof OneToOneIcon = OneToOneIcon;

export default OneToOneIcon;
